package org.mockito.internal.stubbing.defaultanswers;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.internal.InternalMockHandler;
import org.mockito.internal.bytecode.mockmaker.MockCreationValidator;
import org.mockito.internal.creation.settings.CreationSettings;
import org.mockito.internal.stubbing.InvocationContainerImpl;
import org.mockito.internal.stubbing.OngoingStubbing;
import org.mockito.internal.stubbing.StubbedInvocationMatcher;
import org.mockito.internal.util.MockCreationValidator;
import org.mockito.internal.util.MockUtil;
import org.mockito.internal.util.reflection.GenericMetadataSupport;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ReturnsDeepStubs_answer_TriageGen1Test {

    private ReturnsDeepStubs returnsDeepStubs;
    private InvocationOnMock invocation;
    private OngoingStubbing<Object> delegate;
    private Object mockObject;

    // Mocking the protected method behavior via a subclass or spy is tricky in unit tests, 
    // but since we are testing the logic of 'answer', we will use a subclass to override 
    // the protected method 'actualParameterizedType' to control the test flow.
    private static class TestableReturnsDeepStubs extends ReturnsDeepStubs {
        private GenericMetadataSupport metadataToReturn;
        private boolean useMockCreationValidatorLogic = true;

        public TestableReturnsDeepStubs(OngoingStubbing<Object> delegate) {
            super();
            this.delegate = delegate;
        }

        // We need to simulate the delegate field which is part of the internal state
        // Since we cannot easily inject into the private 'delegate', we use reflection or assume 
        // the class structure allows us to set it if it were protected, but here we will 
        // use a spy-like approach or assume the environment allows access.
        // For the sake of this test, we assume the class is accessible.

        @Override
        protected GenericMetadataSupport actualParameterizedType(Object mock) {
            return metadataToReturn;
        }

        // Mocking the 'getMock' method which is likely protected/internal
        protected Object getMock(InvocationOnMock invocation) {
            return mockObject;
        }

        // In a real scenario, 'delegate' is likely a field in the parent class.
        // We'll use reflection to set it.
        public void setDelegate(OngoingStubbing<Object> delegate) throws Exception {
            java.lang.reflect.Field field = ReturnsDeepStubs.class.getDeclaredField("delegate");
            field.setAccessible(true);
            field.set(this, delegate);
        }
    }

    // Mocking GenericMetadataSupport as it's a dependency
    private interface GenericMetadataSupport {
        Class<?> rawType();
    }

    @Before
    public void setUp() throws Exception {
        delegate = mock(OngoingStubbing.class);
        returnsDeepStubs = new TestableReturnsDeepStubs(delegate);
        returnsDeepStubs.setDelegate(delegate);
        invocation = mock(InvocationOnMock.class);
        mockObject = new Object();
    }

    @Test
    public void testAnswer_WhenTypeIsNotMockable_ReturnsDelegateValue() throws Throwable {
        // Arrange
        Class<?> nonMockableType = String.class; // String is generally not mockable in Mockito's validator
        GenericMetadataSupport metadata = mock(GenericMetadataSupport.class);
        when(metadata.rawType()).thenReturn(nonMockableType);

        Object expectedValue = "some value";
        when(delegate.returnValueFor(nonMockableType)).thenReturn(expectedValue);

        Object mockTarget = new Object();
        Method method = String.class.getMethod("length");

        when(invocation.getMock()).thenReturn(mockTarget);
        when(invocation.getMethod()).thenReturn(method);

        // We use a spy/subclass approach to inject the metadata via the protected method
        TestableReturnsDeepStubs spyStub = new TestableReturnsDeepStubs(delegate) {
            @Override
            protected GenericMetadataSupport actualParameterizedType(Object mock) {
                return metadata;
            }
        };
        spyStub.setDelegate(delegate);

        // Act
        Object result = spyStub.answer(invocation);

        // Assert
        assertEquals(expectedValue, result);
    }

    @Test
    public void testAnswer_WhenTypeIsMockable_ReturnsMockedObject() throws Throwable {
        // Arrange
        Class<?> mockableType = Object.class; 
        GenericMetadataSupport metadata = mock(GenericMetadataSupport.class);
        when(metadata.rawType()).thenReturn(mockableType);

        Object mockTarget = new Object();
        Method method = Object.class.getMethod("toString");

        when(invocation.getMock()).thenReturn(mockTarget);
        when(invocation.getMethod()).thenReturn(method);

        TestableReturnsDeepStubs spyStub = new TestableReturnsDeepStubs(delegate) {
            @Override
            protected GenericMetadataSupport actualParameterizedType(Object mock) {
                return metadata;
            }
            @Override
            protected Object getMock(InvocationOnMock invocation) {
                return mockObject;
            }
        };
        spyStub.setDelegate(delegate);

        // Act
        Object result = spyStub.answer(invocation);

        // Assert
        assertSame(mockObject, result);
    }
}
